  },
  "wardrobe_accessories": {
    "garments": [
      {
        "item": "構築的な彫刻風ブレザー",
        "material": "ハリのあるシルク",
        "color": "[ピュアホワイト]",
        "fit": "アヴァンギャルドなオーバーサイズ折り紙カラー"
      }
    ],
    "accessories": [
      {
        "item": "マーブリングコーム",
        "material": "アンティーク真鍮"
      }
    ]
  },
  "environment": {
    "setting": "シュルレアリスム的な紙マーブリング工房",
    "atmosphere": "かすみと埃、宙に漂う流体インクの渦",
    "depth": "柔らかなシアンのボケを伴う浅い被写界深度"
  },
  "lighting": {
    "key": "温かみのある金色の薄明光線",
    "fill": "インク水面からの涼やかなティール光の反射",
    "rim": "かすかな白いエッジライト"
  }
