  "negative_prompt": "模糊，畸形，多余肢体，解剖错误，过曝，生硬阴影，厚重滤镜，微笑，明亮白天，室内环境，塑料感合成皮肤，平滑CG质感",
  "style_tags": [
    "写实摄影",
    "东京夜景街头",
    "皮夹克肖像",
    "暖色霓虹布光",
    "35毫米胶片颗粒"
  ],
  "technical": {
    "aspect_ratio": "3:4",
    "lighting": "暖色钠灯路灯与冷色霓虹轮廓光",
    "camera": "35毫米胶片人像镜头"
  }
}

